INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c4444444-4444-4444-4444-444444444444', 'Acondicionador De Telas Suavitel  Liquido 1000ml', 'acondicionador-de-telas-suavitel-liquido-1000ml-1778', 'Suavitel Acondicionador de Telas Líquido: Suavidad y Frescura que Enamoran Dale a tus prendas el cuidado que se merecen Suavitel Acondicionador de Telas Líquido es la opción ideal para mantener tus telas suaves, frescas y con un aroma duradero. Su fórmula avanzada protege las fibras y facilita el planchado, brindando una experiencia única en cada lavado. Descubre la magia de Suavitel y disfruta de una ropa tan suave como el primer día, con una fragancia que te cautivará. Cuida tu ropa y envuélvete en la delicadeza que Suavitel te proporciona. ¡Pruébalo ahora!', 6856.00, 20, 32, true, true, 'https://www.abastece.co/abastece/images/1778.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Acondicionador De Telas Suavitel Liquido 2800ml', 'acondicionador-de-telas-suavitel-liquido-2800ml-8412', 'Suavitel Acondicionador de Telas Liquido: Suavidad y Frescura que Enamoran Dale a tus prendas el cuidado que se merecen Suavitel Acondicionador de Telas Liquido es la opcion ideal para mantener tus telas suaves, frescas y con un aroma duradero. Su formula avanzada protege las fibras y facilita el planchado, brindando una experiencia unica en cada lavado. Descubre la magia de Suavitel y disfruta de una ropa tan suave como el primer dia, con una fragancia que te cautivara. Cuida tu ropa y envuelvete en la delicadeza que Suavitel te proporciona. ¡Pruebalo ahora!', 15573.00, 20, 29, true, true, 'https://www.abastece.co/abastece/images/8412.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Acondicionador y Protector Cuero 500 ml Binner 106208', 'acondicionador-y-protector-cuero-500-ml-binner-106208-74288', 'Acondicionador y Protector de Cuero Binner Presentación: 500 ml El acondicionador y protector de cuero Binner de 500 ml está formulado especialmente para limpiar, nutrir y proteger superficies de cuero natural o sintético. Ideal para muebles, sillas, calzado, carteras y tapicería automotriz, este producto mantiene el cuero suave, con brillo y libre de grietas. Su fórmula penetra profundamente, restaurando la textura original y creando una capa protectora contra el polvo, la humedad y el desgaste. Una solución práctica y eficaz para prolongar la vida útil de tus artículos de cuero.', 27286.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/74288.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Bonaire Baby Fresh 400ml', 'ambientador-aerosol-bonaire-baby-fresh-400ml-8250', 'Ambientador Bonaire Aerosol Baby Fresh 400 ml: Frescura Suave para Tu Hogar Aroma Delicado que Crea un Ambiente Acogedor Descubre el Ambientador Bonaire Aerosol Baby Fresh de 400 ml, diseñado para llenar tu hogar con un suave y reconfortante aroma que recuerda la frescura de los bebés. Su fórmula efectiva elimina olores desagradables y proporciona una fragancia duradera que transforma cualquier espacio en un entorno acogedor y cálido. Ideal para salas, dormitorios y áreas comunes, este aerosol es perfecto para mantener un ambiente limpio y agradable. ¡Disfruta de la frescura delicada de Bonaire y haz que tu hogar sea aún más acogedor!', 7736.00, 20, 32, true, false, 'https://www.abastece.co/abastece/images/8250.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Bonaire Bambu 400ml', 'ambientador-aerosol-bonaire-bambu-400ml-8352', 'Ambientador Bonaire Aerosol Bambu 400 ml: ¡Refresca tu Espacio con Elegancia! Una Fragancia Natural que Transformará tu Hogar Descubre el Ambientador Bonaire Aerosol Bambu de 400 ml, diseñado para proporcionar una experiencia aromática única. Su fragancia fresca y envolvente evoca la naturaleza, creando un ambiente relajante y agradable en cualquier espacio. Ideal para usar en salas, dormitorios y oficinas, este ambientador te ayudará a eliminar olores no deseados y a disfrutar de un hogar fresco y acogedor. ¡Dale un toque de frescura a tu vida diaria!', 7736.00, 20, 44, true, false, 'https://www.abastece.co/abastece/images/8352.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Bonaire Canela Y Miel 400ml', 'ambientador-aerosol-bonaire-canela-y-miel-400ml-8370', 'Ambientador Bonaire Aerosol Canela y Miel 400 ml: Fragancia natural para un espacio acogedor Fragancia natural para un espacio acogedor Descubre el encanto de la naturaleza con Bonaire Disfruta de un ambiente acogedor. Su exquisita combinación de canela y miel brinda una experiencia aromática única y relajante. Libera notas cálidas y dulces que impregnan cada rincón de tu hogar, creando un entorno acogedor y armonioso. Fácil de usar y de larga duración. ¡Dale a tu espacio vital una sensación reconfortante con este encantador ambientador!', 7874.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/8370.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Bonaire Frutos Rojos Mora Silvestre 400ml', 'ambientador-aerosol-bonaire-frutos-rojos-mora-silvestre-400ml-5371', 'Ambientador Bonaire Aerosol Frutos Rojos 400 ml: Frescura Frutal para Tu Hogar Aroma Vibrante que Revitaliza Cada Espacio Descubre el Ambientador Bonaire Aerosol Frutos Rojos de 400 ml, diseñado para llenar tu hogar con una fragancia fresca y vibrante. Su fórmula potente no solo elimina olores desagradables, sino que también infunde el ambiente con el delicioso aroma de frutos rojos, creando una atmósfera acogedora y revitalizante. Ideal para cualquier habitación, este aerosol transforma tu espacio en un lugar alegre y fresco. ¡Disfruta de la explosión de frescura con Bonaire y transforma tu hogar!', 7874.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/5371.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Bonaire Lavanda 400ml', 'ambientador-aerosol-bonaire-lavanda-400ml-8270', 'Ambientador Bonaire Aerosol Lavanda 400 ml: Frescura y Aromaterapia en tu Hogar Transforma el Ambiente con el Relajante Aroma de Lavanda El Ambientador Bonaire Aerosol Lavanda de 400 ml es la solucion perfecta para crear un ambiente acogedor y relajante en tu hogar. Su delicado aroma a lavanda no solo perfuma el espacio, sino que tambien ayuda a reducir el estres y promover la calma. Ideal para usar en cualquier habitacion, este ambientador es facil de aplicar y proporciona una frescura duradera. ¡Disfruta de la serenidad que el aroma de lavanda puede ofrecerte!', 7874.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/8270.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Bonaire Orquidea De Los Andes 400ml', 'ambientador-aerosol-bonaire-orquidea-de-los-andes-400ml-8792', 'Ambientador Bonaire Aerosol Orquídea de los Andes 400 ml: Frescura y Elegancia para tu Hogar El Toque Perfecto de Aroma Natural para Cada Espacio El Ambientador Bonaire Aerosol Orquídea de los Andes 400 ml ofrece una fragancia suave y envolvente que transforma cualquier ambiente. Con la esencia única de la Orquídea de los Andes, este ambientador proporciona una sensación de frescura duradera, eliminando malos olores y dejando un aroma delicado que perdura en el aire. Ideal para usar en salas, dormitorios, baños y oficinas, crea un ambiente acogedor y relajante con solo un toque. ¡Haz de tu hogar un lugar aún más agradable con Bonaire!', 7874.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/8792.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Bonaire Vainilla 400ml', 'ambientador-aerosol-bonaire-vainilla-400ml-8271', 'Ambientador Bonaire Aerosol Vainilla 400 ml: Dulzura y Calidez para Tu Hogar Perfume Duradero que Transforma Cada Espacio Presentamos el Ambientador Bonaire Aerosol Vainilla de 400 ml, diseñado para llenar tu hogar con un aroma dulce y acogedor. Su fórmula potente elimina olores desagradables y proporciona una fragancia duradera que evoca la calidez de la vainilla. Perfecto para cualquier habitación, este aerosol es ideal para mantener un ambiente agradable y relajante. ¡Disfruta de la frescura y el confort que el aroma de vainilla puede aportar a tu hogar con Bonaire!', 7665.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/8271.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Glade 5 en 1 Campos de Lavanda 400ml', 'ambientador-aerosol-glade-5-en-1-campos-de-lavanda-400ml-8201', 'Ambientador Glade Aerosol 5 en 1 Campos de Lavanda - 400 ml Disfruta de una fragancia fresca y relajante Transforma el ambiente de tu hogar con el Ambientador Glade Aerosol 5 en 1, con la suave y refrescante fragancia de Campos de Lavanda. Su fórmula exclusiva no solo elimina los malos olores, sino que también refresca, revitaliza, purifica y proporciona un ambiente de calma y bienestar. Con 400 ml de contenido, es perfecto para mantener tu hogar siempre fresco y agradable. ¡Haz que cada rincón de tu casa se llene de tranquilidad con Glade!', 10717.00, 20, 48, true, false, 'https://www.abastece.co/abastece/images/8201.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Glade 5 En 1 Fresh Lemon 400ml', 'ambientador-aerosol-glade-5-en-1-fresh-lemon-400ml-8204', 'Ambientador Glade Aerosol 5 en 1 Fresh Lemon 400 ml: Frescura y Versatilidad Elimina Olores y Revitaliza tu Hogar Presentamos el Ambientador Glade Aerosol 5 en 1 Fresh Lemon en presentación de 400 ml, diseñado para ofrecerte una frescura duradera y multifuncional. Su fórmula potente no solo elimina olores desagradables, sino que también refresca y revitaliza el ambiente con un aroma cítrico y energizante de limón. Ideal para cualquier habitación, este aerosol es perfecto para mantener tu hogar con un aroma limpio y acogedor. ¡Disfruta de un espacio fresco y agradable con Glade!', 10737.00, 20, 37, true, false, 'https://www.abastece.co/abastece/images/8204.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Glade 5 en 1 Paraiso Azul 400ml', 'ambientador-aerosol-glade-5-en-1-paraiso-azul-400ml-8202', 'Ambientador Glade Aerosol 5 en 1 – Paraíso Azul 400 ml Fragancia fresca y revitalizante que transforma tu hogar El Ambientador Glade Aerosol 5 en 1 Paraíso Azul de 400 ml es la solución perfecta para refrescar y perfumar tu hogar con una fragancia única y envolvente. Su fórmula avanzada combate los malos olores, desinfecta el aire y proporciona una sensación de frescura duradera. El aroma de Paraíso Azul, fresco y floral, transforma cualquier habitación en un espacio relajante y acogedor. Con su práctico tamaño de 400 ml, es ideal para usar en toda tu casa, desde salas hasta baños. ¡Disfruta de un ambiente limpio, fresco y perfumado con Glade Paraíso Azul!', 10656.00, 20, 49, true, false, 'https://www.abastece.co/abastece/images/8202.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Glade Automatico Repuesto Hawaiian Breeze 175g', 'ambientador-aerosol-glade-automatico-repuesto-hawaiian-breeze-175g-9750', 'Ambientador Glade Automático Repuesto Hawaiian Breeze 175 g: Aroma Tropical y Comodidad Frescura Continua para Cada Rincón de Tu Hogar Descubre el Ambientador Glade Automático Repuesto Hawaiian Breeze de 175 g, diseñado para ofrecerte una fragancia tropical que transforma cualquier espacio. Este repuesto es perfecto para mantener un aroma fresco de manera continua, creando un ambiente acogedor y relajante. Su fórmula evoca la calidez de las islas hawaianas, llenando tu hogar de un perfume exótico. ¡Disfruta de la frescura instantánea y la comodidad del ambientador automático Glade!', 22894.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/9750.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Glade Automatico Repuesto Lavanda Vainilla 175g', 'ambientador-aerosol-glade-automatico-repuesto-lavanda-vainilla-175g-9747', 'Ambientador Glade Automático Repuesto Lavanda Vainilla 175 g: Aromas Relajantes para tu Hogar Frescura Continua y Encanto en Cada Espacio Descubre el Ambientador Glade Automático Repuesto Lavanda Vainilla de 175 g, diseñado para ofrecerte una fragancia equilibrada que combina la suavidad de la lavanda con la dulzura de la vainilla. Este repuesto es perfecto para mantener un ambiente relajante y acogedor en tu hogar, proporcionando una frescura constante sin esfuerzo. Ideal para cualquier habitación, transforma tu espacio en un refugio de calma y confort. ¡Renueva tu hogar con la encantadora mezcla de aromas de Glade!', 22825.00, 20, 51, true, false, 'https://www.abastece.co/abastece/images/9747.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Glade Automatico Repuesto Paraiso Azul 175g', 'ambientador-aerosol-glade-automatico-repuesto-paraiso-azul-175g-5444', 'Ambientador Glade Automático Repuesto – Paraíso Azul 175 gramos Fragancia fresca y constante para mantener tu hogar siempre perfumado El Ambientador Glade Automático Repuesto Paraíso Azul de 175 gramos está diseñado para brindarte frescura constante y una fragancia deliciosa sin esfuerzo. Ideal para usar con el dispositivo Glade automático, este repuesto ofrece una experiencia aromática continua de Paraíso Azul, con notas florales y frescas que transforman tu hogar en un refugio de calma y bienestar. Su duración prolongada y la facilidad de uso lo convierten en la opción perfecta para mantener tus espacios siempre frescos. ¡Haz que tu hogar huela siempre fresco y acogedor con Glade Paraíso Azul!', 22973.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/5444.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Aerosol Glade Automatico Repuesto Vainilla 175gr', 'ambientador-aerosol-glade-automatico-repuesto-vainilla-175gr-3873', 'Repuesto Ambientador Glade Automático 175g: Aroma Vainilla Insumo Institucional para Sistemas Difusores de Fragancia Programada Optimice el mantenimiento de sus ambientes con el repuesto para ambientador automático Glade de 175g. Su fragancia a vainilla proporciona una nota cálida y profesional, ideal para áreas de recepción y oficinas. Diseñado para ofrecer una liberación controlada de alta persistencia, este repuesto garantiza la continuidad operativa de sus sistemas de aromatización, permitiendo una gestión de inventarios más eficaz y asegurando un entorno laboral impecable con el mínimo esfuerzo de reposición.', 22862.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/3873.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Automatico Bonaire Repuesto Vainilla x2', 'ambientador-automatico-bonaire-repuesto-vainilla-x2-73805', 'Ambientador Automático Bonaire Repuesto X2 Vainilla: Gestión de Ambientes Insumo para Difusores Automáticos con Fragancia de Larga Duración Optimice la experiencia en áreas comunes y oficinas con el repuesto para ambientador automático Bonaire. Este pack por 2 unidades de fragancia vainilla garantiza una atmósfera profesional y acogedora de forma continua, reduciendo la frecuencia de mantenimiento. Es la solución eficiente para el control de olores en espacios de alto tráfico, asegurando un entorno laboral agradable y de alto estándar institucional.', 32513.00, 20, 51, true, false, 'https://www.abastece.co/abastece/images/73805.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Automatico Bonaire Repuesto Vainilla Y Floral x2', 'ambientador-automatico-bonaire-repuesto-vainilla-y-floral-x2-74194', '¡Manten tu espacio siempre fresco y agradable! Ambientador Automatico Bonaire Repuesto x2 - Vainilla y Floral Repuestos para ambientadores automaticos Bonaire en presentacion de 2 unidades, con fragancias de vainilla y floral. Perfectos para mantener un aroma suave y duradero en tu hogar o lugar de trabajo.', 32710.00, 20, 52, true, false, 'https://www.abastece.co/abastece/images/74194.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Automatico Glade Paraiso Azul Repuesto x2 270ml', 'ambientador-automatico-glade-paraiso-azul-repuesto-x2-270ml-75182', 'Pack x2 Repuesto Ambientador Glade Automático 270 ml: Paraíso Azul Suministro de Alta Capacidad para Sistemas de Aromatización Programada Asegure la continuidad de sus protocolos de limpieza con el Pack x2 de Repuestos Glade Automático de 270 ml. Diseñados para ofrecer un rendimiento superior en áreas de gran tamaño, estos aerosoles de fragancia Paraíso Azul proporcionan una descarga controlada que mantiene la frescura institucional por hasta 60 días. Su formato doble facilita la gestión de stock para edificios corporativos, garantizando que oficinas y zonas comunes conserven una atmósfera profesional con una menor frecuencia de compra y reposición.', 42395.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/75182.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Bonaire Oil Elec Rep X 3 Und Frutos Rojos 25 Ml', 'ambientador-bonaire-oil-elec-rep-x-3-und-frutos-rojos-25-ml-76188', 'Ambientador Bonaire Oil Eléctrico (Repuesto x 3 Unidades - Frutos Rojos 25 ml) Aromatización constante y sofisticada para espacios profesionales y oficinas El ambientador Bonaire Oil Eléctrico en su presentación de repuestos por tres unidades es un insumo técnico diseñado para ofrecer una fragancia continua y duradera a base de aceites esenciales. Su aroma a frutos rojos proporciona una sensación de frescura y energía, ideal para mantener un ambiente agradable en oficinas, recepciones y salas de juntas. Como producto de aseo institucional, estos repuestos de 25 ml garantizan una difusión uniforme y controlada, optimizando el confort ambiental en áreas de trabajo y espacios comerciales con un bajo consumo energético.', 19496.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/76188.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Electra Oil Repuesto Mandarina Y Toronja x2', 'ambientador-electra-oil-repuesto-mandarina-y-toronja-x2-73801', 'Ambientador Electra Oil Repuesto X2 Mandarina y Toronja: Frescura Frutal para tu Hogar Repuesto para Ambientador Electra Oil con Fragancia Refrescante de Mandarina y Toronja El **Ambientador Electra Oil Repuesto X2 Mandarina y Toronja** proporciona una experiencia de frescura frutal para mantener tu hogar con un aroma agradable y energizante. Su combinacion de mandarina y toronja ofrece una fragancia citrica y refrescante que elimina los malos olores y llena tu espacio con un toque de vitalidad. Cada paquete incluye dos repuestos, ideales para disfrutar de la fragancia por mas tiempo. Perfecto para usar en cualquier habitacion, este ambientador te ayudara a mantener un ambiente fresco y acogedor en todo momento.', 14725.00, 20, 47, true, false, 'https://www.abastece.co/abastece/images/73801.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Electrico Glade Aceite Paraiso Azul x3', 'ambientador-electrico-glade-aceite-paraiso-azul-x3-76537', 'Pack x3 Ambientador Glade Aceite Eléctrico: Fragancia Paraíso Azul Sistema de Aromatización Continua para Gestión de Espacios Corporativos Optimice la experiencia sensorial de su empresa con el Pack de 3 Ambientadores Glade Aceite Eléctrico en fragancia Paraíso Azul. Este formato institucional permite cubrir múltiples áreas simultáneamente, garantizando una liberación constante de aroma en oficinas, recepciones y salas de juntas. Al ser un sistema de evaporación controlada por electricidad, ofrece un rendimiento prolongado y uniforme, reduciendo la frecuencia de reposición y asegurando un entorno laboral siempre fresco con la eficiencia que su operación logística demanda.', 26772.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/76537.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Gel Bonaire Frutos Rojos X170g', 'ambientador-gel-bonaire-frutos-rojos-x170g-75251', 'Ambientador Bonaire Gel Frutos Rojos 170g: Gestión de Ambiente Localizado Control de Olores Autónomo para Áreas de Trabajo y Servicios Sanitarios Optimice la calidad del aire en puntos críticos con el Ambientador Bonaire Gel de 170g. Su fórmula en gel de liberación gradual asegura una fragancia constante a frutos rojos sin necesidad de mantenimiento diario o sistemas eléctricos. Es la solución práctica y económica para mantener cubículos, baños y áreas cerradas con una atmósfera profesional, garantizando frescura continua en espacios que requieren un control de aromas discreto y eficiente.', 5846.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/75251.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Aceite 21ml + Aparto Electrico Manzana Canela', 'ambientador-glade-aceite-21ml-aparto-electrico-manzana-canela-5889', 'Ambientador Glade Aceite Eléctrico Manzana Canela 21 ml: Frescura y Calidez en tu Hogar Perfume Duradero para Crear Ambientes Acogedores Descubre el Ambientador Glade Aceite Eléctrico de Manzana Canela en presentación de 21 ml, ideal para llenar tu hogar con un aroma cálido y acogedor. Su fórmula está diseñada para liberar fragancia de manera continua, proporcionando una experiencia sensorial que combina la frescura de la manzana con la calidez de la canela. Perfecto para cualquier habitación, este ambientador crea un ambiente agradable y envolvente. ¡Transforma tu espacio con el irresistible aroma de Glade!', 17548.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/5889.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Aceite 21ml + Aparto Electrico Vainilla', 'ambientador-glade-aceite-21ml-aparto-electrico-vainilla-5888', 'Ambientador Glade Aceite Unidad Eléctrica – Vainilla 21ml Aroma dulce y envolvente para un hogar acogedor y fresco El Ambientador Glade Aceite en Unidad Eléctrica de 21ml con fragancia de Vainilla ofrece una experiencia aromática suave y duradera que perfuma tu hogar de manera constante. Su diseño de unidad eléctrica dispersa eficientemente la fragancia de vainilla, creando un ambiente cálido y acogedor en cualquier habitación. Perfecto para salas, baños, o cualquier espacio donde desees disfrutar de un aroma delicado y reconfortante. Con el práctico formato de 21ml, puedes disfrutar de esta fragancia durante mucho tiempo. ¡Haz que tu hogar huela delicioso y acogedor con Glade Vainilla!', 17394.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/5888.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Aceite Repuesto Hawaiian Breeze x2 21ml', 'ambientador-glade-aceite-repuesto-hawaiian-breeze-x2-21ml-5588', 'Ambientador Glade Aceite Repuesto x2 Hawaiian Breeze 21 ml: Frescura Tropical para tu Hogar Disfruta de Aromas Exóticos y Revitalizantes Te presentamos el Ambientador Glade Aceite Repuesto x2 Hawaiian Breeze de 21 ml, ideal para llenar tu espacio con un refrescante aroma tropical. Diseñado para usar con los difusores eléctricos Glade, este repuesto ofrece una fragancia duradera que evoca la calidez de las islas hawaianas. Perfecto para cualquier habitación, crea un ambiente acogedor y relajante. ¡Renueva la frescura de tu hogar con el exótico aroma de Hawaiian Breeze!', 20538.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/5588.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Aceite Repuesto Manzana Canela x2 21ml', 'ambientador-glade-aceite-repuesto-manzana-canela-x2-21ml-8259', 'Ambientador Glade Aceite Repuesto x 2 – Manzana Canela 21ml Aroma fresco y cálido que transforma tu hogar Disfruta de una fragancia envolvente y acogedora con el Ambientador Glade Aceite Repuesto x 2 en la deliciosa combinación de Manzana Canela. Cada botella de 21ml te ofrece un aroma fresco y cálido que llena tus espacios de una sensación de limpieza y confort. Ideal para usar en cualquier habitación de tu hogar, este ambientador te brinda un ambiente agradable durante todo el día. Su formato de repuesto es práctico y económico, asegurando que siempre tengas un hogar perfumado y acogedor. ¡Haz que tu casa huela delicioso con Glade Manzana Canela!', 20525.00, 20, 37, true, false, 'https://www.abastece.co/abastece/images/8259.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Aceite Repuesto X2u. Vainilla 21ml', 'ambientador-glade-aceite-repuesto-x2u-vainilla-21ml-8260', 'Ambientador Glade Aceite Repuesto x2 – Vainilla 21ml Una fragancia dulce y reconfortante para tu hogar El Ambientador Glade Aceite Repuesto x2 en Vainilla 21ml ofrece una fragancia dulce y cálida que transforma cualquier espacio de tu hogar en un lugar acogedor. Con su delicada esencia de vainilla, crea un ambiente relajante y agradable que invita a la calma. El paquete incluye dos repuestos de 21ml cada uno, lo que lo convierte en una opción conveniente y duradera para mantener tu hogar con un aroma fresco durante más tiempo. ¡Disfruta de la suavidad y calidez de la vainilla con Glade y haz que tu hogar huela siempre delicioso!', 16689.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/8260.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Aerosol 175g + Aparato Manzana Canela', 'ambientador-glade-aerosol-175g-aparato-manzana-canela-2022', 'Ambientador Glade Automático con Aparato Manzana Canela 175 g: Aromas Acogedores para tu Hogar Frescura Continua y Comodidad en un Solo Dispositivo Te presentamos el Ambientador Glade Automático con Aparato Manzana Canela de 175 g, diseñado para llenar tu hogar con un cálido y delicioso aroma. Este sistema automático proporciona una fragancia constante que combina la frescura de la manzana con la calidez de la canela, creando un ambiente acogedor y atractivo. Perfecto para cualquier habitación, es ideal para quienes buscan comodidad y un toque especial en su espacio. ¡Disfruta de la frescura y el encanto de Glade con este práctico ambientador!', 37211.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/2022.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Aerosol 175g + Aparato Paraiso Azul', 'ambientador-glade-aerosol-175g-aparato-paraiso-azul-75232', 'Kit Ambientador Glade Automático 175g: Solución Integral Paraíso Azul Sistema Programable de Aromatización para Control de Ambientes Profesionales Optimice la gestión sensorial de su empresa con el Kit Ambientador Glade Automático. Este sistema incluye el aparato difusor programable y un repuesto de 175g en fragancia Paraíso Azul, diseñado para ofrecer una descarga controlada y constante en áreas de tráfico moderado. Es la herramienta ideal para mantener oficinas, recepciones y salas de espera con un estándar de frescura superior, permitiendo un control preciso del inventario y garantizando un ambiente acogedor sin requerir intervención manual constante.', 36843.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/75232.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Aparato Toque+Repuesto Paraiso Azul 9g.', 'ambientador-glade-aparato-toquerepuesto-paraiso-azul-9g-71317', 'Ambientador Glade Aparato Toque + Rep. Paraiso Azul 9 grs.: Frescura y Bienestar para tu Hogar Aroma refrescante y duradero para crear un ambiente relajante El Ambientador Glade Aparato Toque + Rep. Paraiso Azul 9 grs. es la combinacion perfecta para disfrutar de un aire fresco y agradable en tu hogar. Con el aparato Glade Toque, solo necesitas activarlo para liberar una fragancia sutil y refrescante de Paraiso Azul, creando una atmosfera relajante y limpia. El repuesto de 9 gramos ofrece una duracion prolongada, eliminando malos olores y dejando un toque de frescura en cada habitacion. Ideal para cualquier espacio, desde salas de estar hasta baños, este ambientador es la opcion perfecta para quienes buscan comodidad, frescura y un ambiente agradable en su hogar.', 12265.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/71317.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Gel Sensations Repuesto Paraiso Azul X2', 'ambientador-glade-gel-sensations-repuesto-paraiso-azul-x2-9804', 'Repuesto Glade Gel Sensations Pack x2: Fragancia Paraíso Azul Aromatización Discreta y de Larga Duración para Áreas Administrativas Garantice un ambiente fresco y profesional con el Repuesto Glade Gel Sensations en Pack x2. Este formato de aromatización sólida es ideal para colocar en estantes, baños o archivadores, liberando una fragancia constante de Paraíso Azul sin necesidad de pilas ni aerosoles. Su tecnología de gel concentrado asegura hasta 60 días de control de olores por unidad, ofreciendo a las empresas una solución económica, segura y de bajo mantenimiento para la gestión de climas laborales agradables en áreas de trabajo individuales y zonas comunes.', 20706.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/9804.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Toque Repuesto Campos de Lavanda x3 9g', 'ambientador-glade-toque-repuesto-campos-de-lavanda-x3-9g-3731', 'Ambientador Glade Toque Repuesto Campos de Lavanda 9g x 3 Unidades: Frescura y Aromas Naturales en Tu Hogar Disfruta de un Ambiente Relajante y Agradable El Ambientador Glade Toque Repuesto Campos de Lavanda, en presentacion de 9g x 3 unidades, te ofrece una forma sencilla de mantener tu hogar fresco y acogedor. Su delicado aroma a lavanda crea un ambiente relajante, ideal para cualquier espacio. Diseñados para ser utilizados con dispensadores Glade, estos repuestos proporcionan una fragancia duradera que transforma la atmosfera de tu hogar en un refugio de tranquilidad. ¡Incorpora la magia de los campos de lavanda en tu vida diaria y disfruta de la frescura en cada rincon!', 22126.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/3731.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Toque Repuesto Manzana Canela 9g', 'ambientador-glade-toque-repuesto-manzana-canela-9g-9038', 'Repuesto Ambientador Glade Toque 9g: Aroma Manzana Canela Insumo para Sistemas de Aromatización Instantánea en Áreas Críticas Asegure una respuesta inmediata ante olores imprevistos con el repuesto para ambientador Glade Toque de 9g. Su fragancia concentrada de manzana canela ofrece una neutralización instantánea y de alta potencia con solo una pulsación, siendo el complemento ideal para baños de oficina y zonas de servicios generales. Este formato compacto y de fácil sustitución garantiza la operatividad de sus dispositivos Glade Toque, optimizando el uso del producto mediante descargas precisas que mantienen el estándar de higiene y confort en su infraestructura corporativa.', 6542.00, 20, 47, true, false, 'https://www.abastece.co/abastece/images/9038.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Glade Toque Repuesto X 2u. Manzana Canela', 'ambientador-glade-toque-repuesto-x-2u-manzana-canela-8794', 'Ambientador Glade Toque Repuesto x 2 Und Manzana Canela Disfruta de un ambiente fresco y agradable con fragancia natural El Ambientador Glade Toque Repuesto x 2 Und Manzana Canela ofrece una combinación deliciosa de aromas de manzana fresca y canela cálida, creando un ambiente acogedor y agradable en cualquier habitación. Con su formato práctico de repuesto, puedes fácilmente recargar tu dispositivo Glade y disfrutar de su fragancia duradera. Ideal para hogares, oficinas o cualquier espacio que desees llenar de frescura y un toque especial. ¡Deja que la fragancia natural transforme tu ambiente!', 16010.00, 20, 44, true, false, 'https://www.abastece.co/abastece/images/8794.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Liquido Lavanda Potente 3000 Ml', 'ambientador-liquido-lavanda-potente-3000-ml-9745', 'Ambientador Líquido Lavanda 3000 ml: Fragancia Duradera para un Ambiente Armonioso Fórmula Concentrada con Aceite Esencial de Manzanilla Marca Potente Disfruta de una fragancia duradera y relajante con el Ambientador Líquido Lavanda 3000 ml. Su fórmula concentrada, enriquecida con aceite esencial de manzanilla, mejora el bienestar y la armonía de los espacios. La marca Potente te brinda un producto de calidad que puedes utilizar en el hogar, oficinas, centros comerciales, instituciones educativas y automóviles. Transforma cualquier ambiente en un lugar acogedor y agradable. Aprovecha la potencia de la lavanda para crear un ambiente sereno y relajante. Disfruta de una experiencia aromática única en cada rincón de tu espacio. Descargar ficha técnica', 18411.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/9745.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Liquido Potente Lavanda 20lt', 'ambientador-liquido-potente-lavanda-20lt-9800', '-Fragancias perdurables -Lavanda con aceite esencial de manzanilla -Fórmula concentrada que permite mejorar el bienestar y armonía de los espacios -Uso en el hogar, oficinas, centros comerciales,instituciones educativas u automóviles Descargar ficha técnica', 108112.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/9800.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Liquido Potente Manzana 20lt', 'ambientador-liquido-potente-manzana-20lt-75084', 'Ambientador Líquido Manzana Potente (Garrafa x 20 Litros) Frescura de larga duración y control de olores para grandes superficies El ambientador líquido Potente con aroma a manzana de 20 litros es un insumo técnico de alta concentración, formulado para perfumar y neutralizar olores en áreas extensas de manera inmediata. Su fragancia frutal proporciona una sensación de limpieza y vitalidad, manteniéndose activa por más tiempo en comparación con ambientadores estándar. Como producto de aseo institucional, esta garrafa de gran formato es la solución más rentable para el mantenimiento de centros comerciales, plantas industriales, edificios de oficinas y grandes instituciones que requieren un control ambiental eficiente con un rendimiento superior.', 108112.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/75084.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Liquido Potente Manzana 3000ml', 'ambientador-liquido-potente-manzana-3000ml-5039', '-Fragancias perdurables -Manzana con aceite esencial de menta -Fórmula concentrada que permite mejorar el bienestar y armonía de los espacios -Uso en el hogar, oficinas, centros comerciales,instituciones educativas u automóviles Descargar ficha técnica', 18411.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/5039.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Aromatizantes Bonaire Pomelo x2 80ml', 'ambientador-varitas-aromatizantes-bonaire-pomelo-x2-80ml-75864', 'Varitas Aromatizantes Bonaire Pomelo 80 ml (Set x 2): Difusión Natural Premium Sistema de Aromatización Continua para Recepciones, Oficinas y Salas de Espera Eleve la percepción de sus espacios profesionales con el Set de Varitas Aromatizantes Bonaire de 80 ml. Este sistema de difusión capilar con fragancia a pomelo ofrece una aromatización constante y sofisticada sin necesidad de energía eléctrica o aerosoles. El paquete por dos unidades permite una gestión eficiente del inventario para múltiples áreas, siendo la opción ideal para mantener recepciones y salas de juntas con un ambiente fresco, moderno y de alto nivel institucional.', 25596.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/75864.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Aromatizantes Glade Alegria Floral Frutos Rojos 100ml', 'ambientador-varitas-aromatizantes-glade-alegria-floral-frutos-rojos-100ml-75862', 'Ambientador Glade Varitas 100 ml: Fragancia Alegría Floral y Frutos Rojos Sistema Difusor de Aroma Permanente para Recepciones y Oficinas Gerenciales Eleve el estándar de sus espacios de trabajo con el Ambientador Glade Varitas Difusoras de 100 ml. Su combinación premium de Alegría Floral y Frutos Rojos ofrece una aromatización equilibrada y persistente que se difunde de manera natural sin necesidad de consumibles eléctricos. Es la solución estética ideal para recepciones, salas de juntas y áreas directivas, donde un ambiente fresco y distinguido es fundamental para proyectar una imagen corporativa sólida y asegurar el bienestar de colaboradores y visitantes.', 16206.00, 20, 34, true, false, 'https://www.abastece.co/abastece/images/75862.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Aromatizantes Glade Frasco Paraiso Azul 100ml', 'ambientador-varitas-aromatizantes-glade-frasco-paraiso-azul-100ml-72590', 'Ambientador Glade Varitas Difusoras 100 ml: Fragancia Paraíso Azul Difusor de Aroma Permanente para Recepciones y Oficinas de Alto Nivel Mejore la imagen de sus espacios profesionales con el Ambientador Glade Varitas Difusoras de 100 ml. Su exclusiva fragancia Paraíso Azul se libera de manera constante a través de varitas de bambú, ofreciendo una experiencia sensorial sofisticada sin necesidad de electricidad o aerosoles manuales. Es la solución estética y funcional ideal para salas de juntas, oficinas gerenciales y áreas de recepción, garantizando un ambiente fresco y distinguido que refuerza el bienestar y la profesionalidad en su entorno laboral.', 16704.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/72590.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Aromatizantes Glade Manzana Canela 100ml', 'ambientador-varitas-aromatizantes-glade-manzana-canela-100ml-75863', 'Ambientador Glade Varitas 100 ml: Fragancia Manzana Canela Sistema Difusor de Aroma Permanente para Oficinas y Salas de Espera Añada una nota de calidez y profesionalismo a sus instalaciones con el Ambientador Glade Varitas Difusoras de 100 ml en fragancia manzana canela. Este sistema de difusión capilar garantiza una liberación constante de aroma, ideal para mantener espacios como recepciones y salas de juntas con una atmósfera acogedora sin depender de aerosoles manuales o conexiones eléctricas. Su presentación elegante y su fórmula de larga duración lo convierten en la opción estratégica para el abastecimiento de oficinas que priorizan el bienestar de sus colaboradores y la buena impresión ante sus visitantes.', 16250.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/75863.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Brizze Vainilla X2 60ml', 'ambientador-varitas-brizze-vainilla-x2-60ml-76484', 'Ambientador Brizze Varitas Rattan Vainilla (Paquete x2 Und - 60 ml) Difusión natural y aroma acogedor para espacios profesionales El ambientador Brizze de varitas de rattan con fragancia a vainilla es un insumo diseñado para ofrecer una aromatización constante y equilibrada sin requerir fuentes de energía externas. Las varitas naturales de rattan absorben y liberan suavemente el perfume, creando un ambiente cálido y confortable ideal para oficinas, salas de espera y recepciones. Como producto de aseo institucional, esta presentación de 60 ml por dos unidades combina funcionalidad y estética, permitiendo mantener una atmósfera profesional y agradable de manera ininterrumpida.', 21010.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/76484.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Brizze Vainilla X3 60ml', 'ambientador-varitas-brizze-vainilla-x3-60ml-75860', 'Ambientador Bonaire Varitas Difusoras 80 ml: Aroma Frutos Rojos Sistema de Aromatización por Capilaridad para Espacios Profesionales Mejore la atmósfera de sus puntos de atención y oficinas con el Ambientador Bonaire Varitas de 80 ml en fragancia frutos rojos. Este difusor de diseño sobrio utiliza tecnología de absorción natural para liberar un aroma persistente y equilibrado, eliminando la dependencia de consumibles eléctricos. Es la solución estratégica para mantener salas de espera y áreas administrativas con una sensación de frescura constante, optimizando el confort ambiental con un mantenimiento nulo.', 34490.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/75860.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Difusoras  Bonaire Pomelo 80ml', 'ambientador-varitas-difusoras-bonaire-pomelo-80ml-9042', 'Ambientador Bonaire Varitas Difusoras Pomelo - 80 ml Revitaliza tu Espacio con el Refrescante Aroma de Pomelo Descubre el Ambientador Bonaire Varitas Difusoras en fragancia Pomelo, presentado en un práctico envase de 80 ml. Este ambientador es ideal para aportar un toque fresco y vibrante a cualquier habitación de tu hogar u oficina. Gracias a su elegante diseño de varitas difusoras, el aroma cítrico del pomelo se dispersa suavemente, creando un ambiente energizante y acogedor. Perfecto para revitalizar tus espacios y disfrutar de una atmósfera estimulante. ¡Deja que el frescor del Pomelo llene tu hogar!', 11912.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/9042.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Difusoras Bonaire  Armonia Floral 80ml', 'ambientador-varitas-difusoras-bonaire-armonia-floral-80ml-9059', 'Ambientador Bonaire Varitas Difusoras Armonia Floral 80 ml: Elegancia y Frescura en tu Hogar Disfruta de un Aroma Delicado y Duradero El Ambientador Bonaire Varitas Difusoras Armonia Floral de 80 ml es la opcion perfecta para llenar tu espacio de un aroma fresco y agradable. Con su sofisticado diseño y varitas difusoras, este ambientador no solo perfuma tu hogar, sino que tambien añade un toque decorativo. Ideal para cualquier habitacion, su fragancia floral crea un ambiente acogedor y relajante. ¡Transforma tu hogar con la armonia de Bonaire!', 11912.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/9059.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Difusoras Bonaire Bambu 80ml', 'ambientador-varitas-difusoras-bonaire-bambu-80ml-75284', 'Ambientador Bonaire Varitas Difusoras Bambú 80 ml: Frescura Natural Transforma tu oficina con la delicada esencia del bambú Disfruta de una atmósfera de serenidad y limpieza con el Ambientador Bonaire de Varitas Difusoras. Su fragancia de Bambú captura la pureza de la naturaleza, liberando un aroma constante y equilibrado en cualquier habitación. Con su elegante presentación de 80 ml, es el complemento ideal para decorar tus espacios mientras eliminas olores no deseados de forma duradera y sofisticada.', 11912.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/75284.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Difusoras Bonaire Frutos Rojos 80ml', 'ambientador-varitas-difusoras-bonaire-frutos-rojos-80ml-1935', 'Ambientador Bonaire Varitas Difusoras Frutos Rojos 80 ml: Frescura Continua en Tu Hogar Aroma Frutal que Crea Ambientes Acogedores Te presentamos el Ambientador Bonaire Varitas Difusoras Frutos Rojos de 80 ml, ideal para proporcionar una fragancia continua y envolvente en tu hogar. Su mezcla vibrante de aromas frutales llena cada rincón con la frescura de los frutos rojos, creando una atmósfera alegre y acogedora. Perfecto para cualquier habitación, este ambientador no solo embellece el espacio, sino que también añade un toque decorativo. ¡Disfruta de la frescura duradera de Bonaire y transforma tu hogar en un refugio aromático!', 11912.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/1935.jpg')
INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Difusoras Bonaire Granadilla 80ml', 'ambientador-varitas-difusoras-bonaire-granadilla-80ml-9061', 'Ambientador Bonaire Varitas Difusoras Granadilla – 80 ml Un toque tropical para refrescar y perfumar tu hogar El Ambientador Bonaire Varitas Difusoras Granadilla es la opción perfecta para quienes buscan un ambiente fresco y perfumado de manera constante. Con su fragancia tropical a granadilla, este ambientador difunde un aroma suave y agradable que transforma cualquier espacio en un lugar acogedor y relajante. Su innovador sistema de varitas difusoras asegura una liberación continua del aroma durante semanas, proporcionando una fragancia duradera sin necesidad de enchufes o aerosoles. Ideal para oficinas, salas de estar, baños y más, el Ambientador Bonaire Granadilla no solo perfuma, sino que también aporta una sensación de frescura y bienestar. ¡Llena tu hogar de un delicioso aroma tropical con este ambientador elegante y práctico de 80 ml!', 11912.00, 20, 34, true, true, 'https://www.abastece.co/abastece/images/9061.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ambientador Varitas Difusoras Bonaire Lavanda 80ml', 'ambientador-varitas-difusoras-bonaire-lavanda-80ml-9060', 'Ambientador Bonaire Varitas Difusoras Lavanda 80 ml: Frescura y Relax en tu Hogar Aroma Suave y Duradero que Transforma el Ambiente El **Ambientador Bonaire Varitas Difusoras Lavanda 80 ml** es la opcion ideal para crear un ambiente relajante y fresco en cualquier espacio. Con su fragancia suave de lavanda, este ambientador aporta una sensacion de tranquilidad y bienestar, perfecta para el hogar, la oficina o cualquier lugar donde se busque un ambiente armonioso. Su presentacion en varitas difusoras asegura una liberacion constante del aroma durante un largo periodo, sin necesidad de electricidad o baterias.', 11912.00, 20, 21, true, true, 'https://www.abastece.co/abastece/images/9060.jpg'),
